const SIDHU_INFO={id:"sidhu-murmu",title:"Sidhu Murmu",quickStats:[{label:"Born",value:"c. 1815, Bhognadih",icon:"📍"},{label:"Died",value:"1856 (executed)",icon:"🕊️"},{label:"Community",value:"Santhal",icon:"🌾"},{label:"Rebellion",value:"Santhal Hul, 1855–56",icon:"🏹"},{label:"Co-Led With",value:"Kanhu, Chand & Bhairav Murmu",icon:"👥"},{label:"Region",value:"Rajmahal Hills, Bengal Presidency",icon:"🗺️"}]},HISTORY_TEXT={title:"From Bhognadih Village to Leading a Rebellion",paragraphs:["Sidhu Murmu was born around 1815 in the village of Bhognadih, in the Santhal Pargana region of the Bengal Presidency (in present-day Jharkhand). He belonged to the Santhal community, an indigenous tribal group of Central-Eastern India.","By the mid-19th century, Santhal communities faced severe exploitation under British colonial land revenue policies, along with abuses from moneylenders (mahajans) and local zamindars, who used debt bondage and land seizures to dispossess Santhal farmers of their land.","In 1855, Sidhu Murmu, along with his brothers Kanhu, Chand, and Bhairav Murmu, called for open rebellion against these oppressive systems, declaring the Santhal Hul (meaning 'revolution' or 'uprising' in the Santhali language). Tens of thousands of Santhals reportedly rose in response, targeting oppressive revenue collectors and moneylenders.","The rebellion was met with a large British military response, and by 1856 it had been suppressed. Sidhu Murmu was captured and executed. Despite its suppression, the Santhal Hul is regarded as a significant and early large-scale organized tribal uprising against British colonial rule, and it directly influenced later colonial administrative reforms in the region."]},TIMELINE_EVENTS=[{era:"c. 1815",title:"Born in Bhognadih",description:"Sidhu Murmu was born into the Santhal community in the village of Bhognadih."},{era:"Early-mid 1850s",title:"Growing Unrest",description:"Santhal communities faced escalating exploitation from colonial revenue policy, moneylenders, and zamindars."},{era:"June 30, 1855",title:"Declaration of the Hul",description:"Sidhu, alongside brothers Kanhu, Chand, and Bhairav Murmu, called a large gathering at Bhognadih and declared open rebellion."},{era:"July–August 1855",title:"Rebellion Spreads",description:"Tens of thousands of Santhals rose against oppressive revenue collectors, moneylenders, and colonial administration across the region."},{era:"Late 1855",title:"British Military Response",description:"Colonial authorities deployed significant military force to suppress the rebellion."},{era:"1856",title:"Capture and Execution",description:"Sidhu Murmu was captured and executed by British authorities, effectively ending the uprising's leadership."},{era:"1855–56 Legacy",title:"Administrative Reforms",description:"The scale of the rebellion contributed to later British administrative changes, including the creation of the Santhal Pargana as a distinct administrative unit."}],REBELLION_POINTS=[{title:"Causes: Land & Debt Exploitation",description:"Oppressive land revenue demands and predatory lending practices by moneylenders (mahajans) had left many Santhal families dispossessed and indebted."},{title:"The Declaration at Bhognadih",description:"On June 30, 1855, a massive gathering at Bhognadih marked the formal declaration of rebellion, led by Sidhu and his brothers."},{title:"Scale of the Uprising",description:"The rebellion drew participation from tens of thousands of Santhals across a wide area of the Rajmahal Hills region."},{title:"Colonial Suppression",description:"The British colonial government responded with substantial military force, ultimately suppressing the rebellion by early 1856."}],SIGNIFICANCE_TEXT={paragraphs:["The Santhal Hul is historically significant as one of the earliest large-scale, organized tribal uprisings against British colonial rule in India, predating the 1857 Rebellion by roughly two years. It demonstrated the capacity for coordinated resistance among indigenous communities facing colonial economic exploitation.","In its aftermath, British authorities created the Santhal Pargana as a distinct administrative division with modified revenue regulations, an acknowledgment of the specific grievances that had driven the uprising. Sidhu Murmu and his brothers are remembered today as important early figures in India's long history of resistance to colonial rule, and their legacy remains especially significant to Santhal and other tribal communities."]},GALLERY_QUERIES=["Santhal Pargana Jharkhand landscape","Santhal tribal community India","Rajmahal Hills region India"],REFERENCES=[{text:"Government of Jharkhand — Santhal Hul historical commemoration records.",link:"#"},{text:"Guha, R. — 'Elementary Aspects of Peasant Insurgency in Colonial India.'",link:"#"},{text:"Datta, K. K. — historical accounts of the Santhal Rebellion of 1855.",link:"#"},{text:"Anthropological Survey of India — studies on Santhal community history.",link:"#"}];